/// The row's fields that hold a number (null where not finite).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum RowNum {
    /// Most samples of a push channel have nothing out, so the flight and the
    /// requests out also read over the samples with any (`*_busy_*`), with the
    /// share of samples with requests out (`reqs_out_share`).
    WindowPP(u16),
    /// The bytes of the ANNOUNCEs with entries that reached the seed per second
    /// of the stream (over stream_secs).
    ///
    /// Unit: bytes/s.
    AnnounceBps,
    /// The bytes of the ANNOUNCEs with entries that reached the seed, as a
    /// share of what the viewers sent.
    ///
    /// Unit: fraction.
    AnnounceShare,
    /// With clock skew, the share of the stream's chunks the honest viewers of
    /// clock class `class` read, of those due them (Sim::delivered, with
    /// arrivals or departures).
    ClockClassDelivery(u16),
    /// The cross-traffic swarm's delivery (CrossReport); 0 without one.
    CrossDelivery,
    /// Of the STREAM_REQUESTs the honest viewers declined over the samples, the
    /// share declined in a second in which the viewer used under half its
    /// uplink (Shape::declines_idle over Shape::declines); left out without
    /// declines.
    ///
    /// ppspp: A share of declines; strims-sim's `declined` and
    /// `declined_wrongly` are counts, by its meter's rate.
    DeclinesIdle,
    /// The share of what the viewers were owed that they read: delivered over
    /// written frames of the first swarm, summed over its viewers, each owed
    /// every frame the seed wrote while it was there (Report::owed), those
    /// written while it was down included; a media swarm's viewer is owed the
    /// frames from its first on.
    ///
    /// ppspp: The chunks read over the chunks due, summed over the honest
    /// viewers whose places were never taken again (Sim::delivered: an arrival
    /// is due the chunks from its reader's start, a departure those published
    /// CAUGHT_UP before it left).
    ///
    /// Unit: fraction.
    Delivery,
    /// Of the viewers' (viewer, stream) samples once a second from DEPTH_WARM
    /// after the stream's start, the share that reach the seed through a chain
    /// of open parents `hops` hops long, 1 to 6 (Report::depths).
    ///
    /// ppspp: Of the honest (viewer, stream) samples (Shape::depth), the share
    /// through a chain of open parents `hops` hops from the seed, up to
    /// DEPTH_HOPS.
    DepthHops(u16),
    /// Of the viewers' (viewer, stream) samples, the share whose chain of open
    /// parents is a cycle (Report::depths).
    ///
    /// ppspp: Of the honest (viewer, stream) samples, the share in a cycle.
    DepthCycle,
    /// Of the viewers' (viewer, stream) samples, the share through a chain of
    /// open parents deeper than 6 hops (Report::depths).
    ///
    /// ppspp: Of the honest (viewer, stream) samples, the share through a chain
    /// deeper than DEPTH_HOPS.
    DepthDeeper,
    /// Of the viewers' (viewer, stream) samples once a second from DEPTH_WARM
    /// after the stream's start, the share with no open parent
    /// (Report::depths).
    ///
    /// ppspp: Of the honest (viewer, stream) samples (Shape::depth), the share
    /// with no open parent.
    DepthNone,
    /// Of the viewers' (viewer, stream) samples, the share whose chain ends at
    /// a viewer with no open parent: a subtree rooted in pull (Report::depths).
    ///
    /// ppspp: Of the honest (viewer, stream) samples, the share whose chain
    /// ends at a viewer with no open parent.
    DepthPullRooted,
    /// The mean size of the vnic frames the honest hosts wrote: frame bytes
    /// over frames.
    ///
    /// ppspp: The mean size of the frames with ppspp data every node sent
    /// (Sent::frame_bytes over Sent::frames).
    ///
    /// Unit: bytes.
    FrameBytesMean,
    /// Of the seed's push slots (one stream at one neighbour) over the samples
    /// after the warm-up, the share at free riders.
    FreeRiderSlots,
    /// Of the seed's push slots (one stream at one neighbour) over the samples
    /// after the warm-up, the share at grabbers.
    GrabberSlots,
    /// The honest viewers' mean share of their channels whose peer asked them
    /// for lazy HAVEs, over their meter samples with channels while a swarm
    /// streams (Report::lazy_shares).
    ///
    /// ppspp: Over the samples of honest viewers with channels, the mean share
    /// of their channels whose peer asked them for lazy HAVEs (Shape::lazy).
    ///
    /// Unit: fraction.
    HaveLazyInShare,
    /// The honest viewers' mean share of their channels whose peer they ask for
    /// lazy HAVEs, over their meter samples with channels while a swarm streams
    /// (Report::lazy_shares).
    ///
    /// ppspp: Over the samples of honest viewers with channels, the mean share
    /// of their channels whose peer they ask for lazy HAVEs (Shape::lazy).
    ///
    /// Unit: fraction.
    HaveLazyOutShare,
    /// Per pair of consecutive samples after the warm-up and honest whole-copy
    /// holder in both, its median share of its copy got as on-time pushes
    /// (Sim::holder_copies).
    HolderCopy,
    /// Per pair of consecutive samples after the warm-up and honest whole-copy
    /// holder in both, the share of those intervals in which it got under
    /// HOLDER_WHOLE of its copy as on-time pushes (Sim::holder_copies).
    HolderShort,
    /// Of the honest viewers' streams over the samples after the warm-up, the
    /// share whose parent is a liar.
    LiarGrafts,
    /// How long a liar held a copy at a time, the longest, in s.
    ///
    /// Unit: s.
    LiarHoldMaxS,
    /// How long a liar held a copy at a time, the mean, in s.
    ///
    /// Unit: s.
    LiarHoldS,
    /// Of the seed's push slots (one stream at one neighbour) over the samples
    /// after the warm-up, the share at liars.
    LiarSlots,
    /// The stream's rate, in Mbit/s (Config::stream_rate).
    Mbit,
    /// A media swarm's media rate: media bytes over the stream's seconds, in
    /// kbit/s; left out without media.
    MediaKbit,
    /// Per sample of each honest node whose upload meter has a capacity: the
    /// capacity (the relay busy-time reading, `PushStats::upload_capacity`, the
    /// seed's too) over the node's true uplink, for the seed, relays and the
    /// other viewers: the row's `meter_seed_p*`, `meter_relays_p*` and
    /// `meter_others_p*`.
    ///
    /// ppspp: Pair: strims-sim's `meter_{role}` hold the same reading as one
    /// list of p10/p50/p90 by role: `seeds`, `forwarders` (hosts that answered
    /// a STREAM_REQUEST, not this sim's `relays`) and `others`.
    MeterRolePP(u16),
    /// Messages per channel payload, over the honest hosts' outbound ppspp
    /// (ChannelMetrics messages over payloads).
    MsgsPerPayload,
    /// The median over the honest hosts of no role (Report::roles: neither seed
    /// nor forwarder) of their overhead per second over their uplinks.
    ///
    /// ppspp: Over the honest viewers that accepted no subscription (leaves),
    /// each over the time it was there.
    OvhLeafP50,
    /// The p90 over the honest hosts of no role (Report::roles) of their
    /// overhead per second over their uplinks.
    ///
    /// ppspp: Over the honest viewers that accepted no subscription (leaves),
    /// each over the time it was there.
    OvhLeafP90,
    /// The median over the honest forwarders (Report::roles) of their overhead
    /// per second over their uplinks: wire bytes less ppspp chunk data, over
    /// the uplink times the run's seconds.
    ///
    /// ppspp: Over the honest viewers that accepted a subscription (relays),
    /// each over the time it was there.
    OvhRelayP50,
    /// The seed's overhead per second over its uplink: wire bytes less ppspp
    /// chunk data, over the uplink times the run's seconds.
    OvhSeed,
    /// Parent changes (prunes and switches) per viewer-minute: over the first
    /// swarm's viewers for the stream's span, or with arrivals or departures
    /// per minute each viewer was there.
    ///
    /// ppspp: Prunes and switches (PushStats) per honest viewer-minute after
    /// the warm-up; with arrivals or departures per minute each honest viewer
    /// was there after its own warm-up (at least a minute).
    ///
    /// Unit: per minute.
    ParentChangesPerMin,
    /// In WAN mode, the median over the honest forwarders and others of their
    /// packets per second through their uplinks.
    ///
    /// ppspp: The median over the honest viewers of their packets up per second
    /// they were there.
    PpsP50,
    /// In WAN mode, the p90 over the honest forwarders and others of their
    /// packets per second through their uplinks.
    ///
    /// ppspp: The p90 over the honest viewers of their packets up per second
    /// they were there.
    PpsP90,
    /// When the run ended (Report::finish), in s from t0: the span the seed's
    /// and the viewers' rates are over.
    ///
    /// ppspp: Pair, if their definitions match: strims-sim's `sim_secs`.
    ///
    /// Unit: s.
    ReadsEndS,
    /// Over the samples, the honest viewers with at least one push subscriber
    /// over the honest viewers (Shape::relays, Shape::viewers).
    ///
    /// Unit: fraction.
    RelayShare,
    /// Most samples of a push channel have nothing out, so the flight and the
    /// requests out also read over the samples with any (`*_busy_*`), with the
    /// share of samples with requests out (`reqs_out_share`).
    ///
    /// Unit: fraction.
    ReqsOutShare,
    /// Of the chunks the seed sent, the share that were distinct chunks
    /// (distinct_chunks_sent over chunks_sent).
    SeedDistinct,
    /// The seed's wire bytes up over the run, in MB.
    SeedMbUp,
    /// The seed's packets through its uplink per second of the run (WAN mode in
    /// strims-sim, left out outside it).
    SeedPps,
    /// Of the chunks the seed sent, the share that answered requests: chunks
    /// sent less pushed, over chunks sent (its swarm stats).
    ///
    /// Unit: fraction.
    SeedPullShare,
    /// The seed's share of the upload: its bytes over the seed's, viewers' and
    /// relays' together (UploadDistribution::seed_share, everything they wrote
    /// to their links).
    ///
    /// ppspp: The seed's share of all data bytes sent (Sim::uploaded over every
    /// node, none from a greedy viewer).
    ///
    /// Unit: fraction.
    SeedShare,
    /// The seed's push subscriptions (stream slots), mean over the samples
    /// after the warm-up.
    ///
    /// ppspp: Distinct from strims-sim's `seed_budget` and `seed_copies`.
    SeedSlots,
    /// The seed's use of its uplink: its wire bytes up over its uplink times
    /// the run's span (reads_end_s).
    SeedUplink,
    /// The seed's wire bytes through its uplink, its transports' framing
    /// included, over the bytes it wrote to its sockets.
    ///
    /// ppspp: The seed's wire bytes up over them less its TCP/IP headers
    /// (Sent::transport_bytes).
    SeedWirePerWritten,
    /// A media swarm's stream rate: the bytes its seed sent of the stream over
    /// the stream's seconds, in kbit/s; left out without media.
    SentKbit,
    /// When the seed's holders (AllocSample::holders) last changed after the
    /// stream started, in s.
    ///
    /// Unit: s.
    SettledS,
    /// In WAN mode, the small packets over the packets through every host's
    /// uplink, acknowledgements counted small.
    ///
    /// ppspp: Small packets over the packets through every node's uplink.
    ///
    /// Unit: fraction.
    SmallPacketShare,
    /// The row's playback columns, as the ppspp sim's rows have them: per delay
    /// `D` of `DELAYS_MS`, `swarm`'s viewers' playouts of what they read
    /// (`playout::play`, the tables' `stalls`), each viewer from its playback's
    /// start to its last frame's play, or its departure if that came first
    /// (`Totals`): the stalls per minute played (`stalls_per_min_D`), the share
    /// of it stalled (`stalled_share_D`), and the mean ms from each one's join
    /// (its reader's start, or the stream's if later, as `Report::joins` times
    /// it) to its playback's start (`startup_ms_D`); with hostile hosts, the
    /// honest viewers' too, with `_honest`.
    ///
    /// ppspp: The playback columns, as strims-sim's rows have them: per delay
    /// `D` of `DELAYS_MS`, the honest viewers' playouts of what they read
    /// (`playout::play`, the tables' `stalls`), each viewer from its playback's
    /// start to its last chunk's play, or its leaving for good if that came
    /// first (`Totals`): the stalls per minute played (`stalls_per_min_D`), the
    /// share of it stalled (`stalled_share_D`), and the mean ms from each one's
    /// join (its arrival, or the stream's start if later) to its playback's
    /// start (`startup_ms_D`).
    ///
    /// Unit: fraction.
    StalledShareDelayPop(u16),
    /// The row's playback columns, as the ppspp sim's rows have them: per delay
    /// `D` of `DELAYS_MS`, `swarm`'s viewers' playouts of what they read
    /// (`playout::play`, the tables' `stalls`), each viewer from its playback's
    /// start to its last frame's play, or its departure if that came first
    /// (`Totals`): the stalls per minute played (`stalls_per_min_D`), the share
    /// of it stalled (`stalled_share_D`), and the mean ms from each one's join
    /// (its reader's start, or the stream's if later, as `Report::joins` times
    /// it) to its playback's start (`startup_ms_D`); with hostile hosts, the
    /// honest viewers' too, with `_honest`.
    ///
    /// ppspp: The playback columns, as strims-sim's rows have them: per delay
    /// `D` of `DELAYS_MS`, the honest viewers' playouts of what they read
    /// (`playout::play`, the tables' `stalls`), each viewer from its playback's
    /// start to its last chunk's play, or its leaving for good if that came
    /// first (`Totals`): the stalls per minute played (`stalls_per_min_D`), the
    /// share of it stalled (`stalled_share_D`), and the mean ms from each one's
    /// join (its arrival, or the stream's start if later) to its playback's
    /// start (`startup_ms_D`).
    StallsPerMinDelayPop(u16),
    /// When the stream ended, in s from t0: the stream's length (stream_secs)
    /// after its start at 1 s.
    ///
    /// Unit: s.
    StreamEndS,
    /// A media swarm's stream bytes over its media bytes; left out without
    /// media.
    StreamPerMedia,
    /// A media swarm's units signed a second (each peer's signature
    /// verifications); left out without media.
    ///
    /// Unit: s.
    UnitsPerS,
    /// The p-th percentile over the first swarm's viewers and relays of their
    /// uplink use: bytes written to sockets over the uplink for the stream's
    /// span (with arrivals or departures, the span each was there for).
    ///
    /// ppspp: Over the honest viewers: wire bytes up over the uplink for the
    /// time each was there.
    ViewerUtilPP(u16),
    /// Every host's upload per media byte per viewer: the bytes uploaded over
    /// the media bytes times the viewers; left out without media.
    WirePerMedia,
    /// The wire bytes through every uplink (`up_wire`) over the bytes of the
    /// stream the honest viewers read (`useful_bytes`).
    WirePerUseful,
}

