/// The row's fields that hold text.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum RowText {
    /// In WAN mode, the access link of the config's first site (the seed's);
    /// `-` outside WAN mode.
    Access,
    /// The run's arrivals profile, its knob's text (STRIMS_SIM_ARRIVALS,
    /// SIM_ARRIVALS); left out for one with every viewer from the start
    /// (strims-sim) or without arrivals or departures (the ppspp sim).
    Arrivals,
    /// The allocation the job ran: for cable-seed, its seed policy's allocation
    /// (SIM_SEED_POLICY: adaptive or admission); for an AbScenario, its
    /// AllocCase (SIM_CASE, AdaptiveQos by default).
    Case,
    /// The clock skew the run's clocks had (STRIMS_SIM_CLOCK_SKEW,
    /// SIM_CLOCK_SKEW): its knob's text.
    ///
    /// None is written as an empty field.
    ClockSkew,
    /// The run's departures profile, its knob's text (STRIMS_SIM_DEPART,
    /// SIM_DEPART); left out without departures.
    Depart,
    /// A media swarm's encoder (MediaSpec); left out without media.
    Media,
    /// A digest of the honest viewers' reads as 16 hex digits, which a change
    /// that moves only readers changes and the trace may not.
    ///
    /// ppspp: An FNV digest over each honest viewer's node and its reads'
    /// digest, in node order (Sim::reads_hash).
    ReadsHash,
    /// The run's capture directory name: its seed and a hash of its config
    /// (run_tag).
    RunTag,
    /// The scenario's name.
    ///
    /// ppspp: SIM_SCENARIO's: cable-seed (the default), or the AbScenario the
    /// job ran.
    Scenario,
    /// A media swarm's signing policy (MediaSpec); left out without media.
    Sign,
    /// The run's trace digest as 16 hex digits: what the nodes sent, which a
    /// rerun must reproduce.
    Trace,
}

impl RowText {
    /// The name, as ppspp writes it.
    pub(crate) fn name(self) -> &'static str {
        match self {
            RowText::Access => "access",
            RowText::Arrivals => "arrivals",
            RowText::Case => "case",
            RowText::ClockSkew => "clock_skew",
            RowText::Depart => "depart",
            RowText::Media => "media",
            RowText::ReadsHash => "reads_hash",
            RowText::RunTag => "run_tag",
            RowText::Scenario => "scenario",
            RowText::Sign => "sign",
            RowText::Trace => "trace",
        }
    }
}

impl sealed::Sealed for RowText {}

impl Key for RowText {
    fn name(self) -> &'static str {
        RowText::name(self)
    }
}

