/// The place of the name `name` formats among a family's `names`.
// A name the document doesn't give the sim is the sim's mistake, never
// a peer's input: it stops the run.
#[allow(clippy::panic)]
fn of(names: &[&'static str], name: Arguments) -> u16 {
    let name = name.to_string();
    match names.iter().position(|n| *n == name) {
        Some(i) => i as u16,
        None => panic!("{name}: crates/strims-wan/fields.toml gives ppspp no such name"),
    }
}

/// The name at place `i` among a family's `names`.
fn at(names: &[&'static str], i: u16) -> &'static str {
    names.get(usize::from(i)).copied().unwrap_or_default()
}

#[cfg(test)]
mod tests {
    use std::fmt::Display;

    fn strings<T: Display>(v: impl IntoIterator<Item = T>) -> Vec<String> {
        v.into_iter().map(|x| x.to_string()).collect()
    }

    /// Each family's params whose values are the code's arrays hold
    /// those arrays, in order.
    #[test]
    fn params_are_the_codes_arrays() {
        assert_eq!(
            [strings(crate::CLOCK_CLASSES)].concat(),
            ["lt_100ms", "lt_2s", "lt_15s", "le_10min",],
            "rows clock_{{class}}'s class"
        );
        assert_eq!(
            [strings(crate::CLOCK_CLASSES)].concat(),
            ["lt_100ms", "lt_2s", "lt_15s", "le_10min",],
            "rows clock_{{class}}_delivery's class"
        );
        assert_eq!(
            [strings(crate::CLOCK_CLASSES)].concat(),
            ["lt_100ms", "lt_2s", "lt_15s", "le_10min",],
            "rows clock_{{class}}_lag_p99_ms's class"
        );
        assert_eq!(
            [strings(crate::CLOCK_CLASSES)].concat(),
            ["lt_100ms", "lt_2s", "lt_15s", "le_10min",],
            "rows clock_{{class}}_viewers's class"
        );
        assert_eq!(
            [strings(1..=crate::DEPTH_HOPS)].concat(),
            ["1", "2", "3", "4", "5", "6",],
            "rows depth_{{hops}}'s hops"
        );
        assert_eq!(
            [strings(strims_wan::playout::DELAYS_MS)].concat(),
            ["1250", "4250",],
            "rows stalled_share_{{delay}}{{pop}}'s delay"
        );
        assert_eq!(
            [strings(strims_wan::playout::DELAYS_MS)].concat(),
            ["1250", "4250",],
            "rows stalls_per_min_{{delay}}{{pop}}'s delay"
        );
        assert_eq!(
            [strings(strims_wan::playout::DELAYS_MS)].concat(),
            ["1250", "4250",],
            "rows startup_ms_{{delay}}{{pop}}'s delay"
        );
        assert_eq!(
            [strings(crate::NODE_COLS), strings(crate::WAIT_COLS)].concat(),
            [
                "timeouts",
                "wasted",
                "answers_refused",
                "answers_dropped",
                "switched",
                "shed",
                "sheds_sent",
                "have_bytes",
                "ack_bytes",
                "request_bytes",
                "announce_bytes",
                "stream_bytes",
                "session_bytes",
                "ping_bytes",
                "header_bytes",
                "integrity_bytes",
                "data_bytes",
                "payloads",
                "have_only_payloads",
                "retransmits",
                "drops",
                "push_waits",
                "push_wait_p50_ms",
                "push_wait_p99_ms",
                "answer_waits",
                "answer_wait_p50_ms",
                "answer_wait_p99_ms",
            ],
            "columns.bins {{who}}_{{counter}}'s counter"
        );
        assert_eq!(
            [strings(crate::NODE_COLS), strings(crate::WAIT_COLS)].concat(),
            [
                "timeouts",
                "wasted",
                "answers_refused",
                "answers_dropped",
                "switched",
                "shed",
                "sheds_sent",
                "have_bytes",
                "ack_bytes",
                "request_bytes",
                "announce_bytes",
                "stream_bytes",
                "session_bytes",
                "ping_bytes",
                "header_bytes",
                "integrity_bytes",
                "data_bytes",
                "payloads",
                "have_only_payloads",
                "retransmits",
                "drops",
                "push_waits",
                "push_wait_p50_ms",
                "push_wait_p99_ms",
                "answer_waits",
                "answer_wait_p50_ms",
                "answer_wait_p99_ms",
            ],
            "columns.node_bins {{counter}}'s counter"
        );
    }
}
